function validate([wordsContainer, wordsQuery]) {
  for (const [name, list] of [['wordsContainer', wordsContainer], ['wordsQuery', wordsQuery]]) {
    if (!Array.isArray(list) || list.length < 1 || list.length > 10000) return name + ' needs 1 to 10000 strings.';
    let total = 0;
    for (const s of list) {
      if (typeof s !== 'string' || s.length < 1 || s.length > 5000) return 'Each string in ' + name + ' has 1 to 5000 characters.';
      if (!/^[a-z]+$/.test(s)) return 'Strings may contain only lowercase letters.';
      total += s.length;
    }
    if (total > 500000) return 'The strings in ' + name + ' total at most 500000 characters.';
  }
  return null;
}

