function stringIndices(wordsContainer, wordsQuery) {
  const root = { children: {}, best: 0 };

  for (let i = 0; i < wordsContainer.length; i++) {
    const word = wordsContainer[i];
    let node = root;
    if (word.length < wordsContainer[node.best].length) {
      node.best = i;
    }
    for (let j = word.length - 1; j >= 0; j--) {
      const ch = word[j];
      if (!node.children[ch]) {
        node.children[ch] = { children: {}, best: i };
      }
      node = node.children[ch];
      if (word.length < wordsContainer[node.best].length) {
        node.best = i;
      }
    }
  }

  const answer = [];
  for (const query of wordsQuery) {
    let node = root;
    for (let j = query.length - 1; j >= 0; j--) {
      const next = node.children[query[j]];
      if (!next) {
        break;
      }
      node = next;
    }
    answer.push(node.best);
  }
  return answer;
}

