function stringIndices(wordsContainer, wordsQuery) {
  const commonSuffix = (a, b) => {
    let len = 0;
    while (len < a.length && len < b.length && a[a.length - 1 - len] === b[b.length - 1 - len]) len++;
    return len;
  };
  return wordsQuery.map((query) => {
    let pick = -1;
    let pickShared = -1;
    wordsContainer.forEach((word, idx) => {
      const shared = commonSuffix(word, query);
      if (shared > pickShared || (shared === pickShared && word.length < wordsContainer[pick].length)) {
        pick = idx;
        pickShared = shared;
      }
    });
    return pick;
  });
}

