function generate(rand, size) {
  const large = size === 'large';
  const letters = large ? 'abc' : (rand() < 0.5 ? 'ab' : 'abc');
  const word = (maxLen) => {
    const len = 1 + Math.floor(rand() * maxLen);
    let s = '';
    for (let i = 0; i < len; i++) s += letters[Math.floor(rand() * letters.length)];
    return s;
  };
  const containerSize = large ? 1000 : 1 + Math.floor(rand() * 5);
  const querySize = large ? 1000 : 1 + Math.floor(rand() * 5);
  const maxLen = large ? 15 : 5;
  const wordsContainer = Array.from({ length: containerSize }, () => word(maxLen));
  const wordsQuery = Array.from({ length: querySize }, () => {
    // Sometimes reuse a container string's ending so that long matches happen.
    if (rand() < 0.4) {
      const base = wordsContainer[Math.floor(rand() * wordsContainer.length)];
      const cut = Math.floor(rand() * base.length);
      const extra = rand() < 0.5 ? word(3) : '';
      return extra + base.slice(cut);
    }
    return word(maxLen);
  });
  return [wordsContainer, wordsQuery];
}
